#include <iostream>
#include <stdexcept>
#include <vector>

void replace_pages(std::vector<int>& target, const std::vector<int>& input)
{
    std::vector<int> prepared = input;
    for (int value : prepared)
        if (value < 0) throw std::invalid_argument("negative page count");
    target.swap(prepared);
}

int main()
{
    std::vector<int> pages{4, 6};
    try {
        replace_pages(pages, std::vector<int>{8, -1});
    } catch (const std::invalid_argument&) {
        std::cout << "Rejected\n";
    }
    std::cout << pages[0] << ' ' << pages[1] << '\n';
    replace_pages(pages, std::vector<int>{8, 10});
    std::cout << pages[0] << ' ' << pages[1] << '\n';
}
